const item = $input.first();

if (item.binary && item.binary.productImage) {
  // 强制从 n8n 的硬盘/内存中提取真实的二进制 Buffer
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'productImage');
  // 将真实的二进制文件转换为 base64 字符串
  const base64Data = buffer.toString('base64');
  const mimeType = item.binary.productImage.mimeType;

  // 拼接完整的 Data URL 并塞回 json
  item.json.product_image_base64 = `data:${mimeType};base64,${base64Data}`;
}

return item;

// 1. R2 公网访问域名
const publicDomain = 'https://YOUR_PUBLIC_R2_DOMAIN.r2.dev';

// 2. 从表单中获取唯一的表单提交时间标识（与 S3 节点的命名规则保持 100% 一致）
const formInput = $('产品信息').first().json;
const timeKey = formInput.submittedAt || 'temp';

// 3. 拼接出精准对应的文件名，绝对不会出现时间戳漂移
const fileKey = `products/product_${timeKey}.png`;

// 4. 组成完整的直链 URL
const imageUrl = `${publicDomain}/${fileKey}`;

return {
  json: {
    ...formInput,
    product_public_image_url: imageUrl
  }
};

// 读取 📹 提取视频URL1 中的全部元数据（customer_email / customer_name / product_name / total_duration / variant_index / hook_angle 等）
const meta = $('📹 提取视频URL').first().json;

// R2 公网桶域名，生成永久直链
const r2Base = 'https://YOUR_PUBLIC_R2_DOMAIN.r2.dev';

return $input.all().map((item) => {
  // 以 📹 提取视频URL1 的元数据为准，完整透传给下游
  const json = { ...meta };

  // 文件名与 ☁️ 上传视频到R2 节点完全一致（时间戳来自 📹 提取视频URL1 统一生成的 video_ts）
  const variantIndex = meta.variant_index || 1;
  const key = `videos/video_${meta.video_ts}_${variantIndex}.mp4`;

  // 将临时 Seedance 链接覆盖为永久有效的 R2 直链
  json.final_video_url = `${r2Base}/${key}`;

  return { json, binary: item.binary };
});

let item = $input.first().json;
let text = '';

// 1. 抓取大模型返回文本
if (item.choices?.[0]?.message?.content) {
    text = item.choices[0].message.content;
} else if (item.content && typeof item.content === 'string') {
    text = item.content;
} else if (item.content?.parts?.[0]?.text) {
    text = item.content.parts[0].text;
} else if (item.candidates?.[0]?.content?.parts?.[0]?.text) {
    text = item.candidates[0].content.parts[0].text;
} else if (item.output) {
    text = typeof item.output === 'string' ? item.output : JSON.stringify(item.output);
} else if (item.text) {
    text = item.text;
}

// 2. 清理 Markdown 标记与首尾空白
text = text.replace(/```json/gi, '').replace(/```/g, '').trim();

// 3. 四级超级容错解析
let data = {};
let parsed = false;

// 级别 1：标准 JSON 解析
try {
    let match = text.match(/\{[\s\S]*\}/);
    data = match ? JSON.parse(match[0]) : JSON.parse(text);
    parsed = true;
} catch (e) {}

// 级别 2：清洗尾随逗号与非法控制字符后解析
if (!parsed) {
    try {
        let clean = text.replace(/[\u0000-\u001F\u007F-\u009F]/g, " ")
                        .replace(/,\s*([\}\]])/g, "$1"); // 去除尾随逗号
        let match = clean.match(/\{[\s\S]*\}/);
        data = match ? JSON.parse(match[0]) : JSON.parse(clean);
        parsed = true;
    } catch (e) {}
}

// 级别 3：JS 动态求值解析（兼容单引号与未严格转义字符）
if (!parsed) {
    try {
        let match = text.match(/\{[\s\S]*\}/);
        if (match) {
            data = (new Function("return " + match[0]))();
            parsed = true;
        }
    } catch (e) {}
}

// 级别 4：终极正则提取兜底（即便 JSON 完全损坏也能把字段精准抠出来）
if (!parsed) {
    const extract = (key) => {
        const reg = new RegExp(`"${key}"\\s*:\\s*"([\\s\\S]*?)(?="\\s*,\\s*"|"$|\\s*\\})`, 'i');
        const m = text.match(reg);
        return m ? m[1].replace(/\\n/g, '\n').replace(/\\"/g, '"').trim() : '';
    };

    data = {
        product_name: extract('product_name'),
        category: extract('category'),
        visual_anchor: extract('visual_anchor') || extract('visualAnchor'),
        target_audience: extract('target_audience'),
        extreme_pain_point: extract('extreme_pain_point') || extract('pain_point'),
        core_solution: extract('core_solution'),
        visual_hook_suggestion: extract('visual_hook_suggestion'),
        suggested_style: extract('suggested_style')
    };
}

// 4. 安全提取上游节点数据
let formData = {};
try { formData = $('产品信息').first().json || {}; } catch (e) {}

let productPublicImageUrl = '';
try { productPublicImageUrl = $('📎 提取产品图URL').first().json.product_public_image_url || ''; } catch (e) {}

let productImageBase64 = '';
try { productImageBase64 = $('提取产品图片').first().json.product_image_base64 || ''; } catch (e) {}

// 5. 标准化格式输出
return [{
  json: {
    product_name: data.product_name || '',
    category: data.category || '',
    visual_anchor: data.visual_anchor || data.visualAnchor || '',
    visual_features: Array.isArray(data.visual_features) ? data.visual_features.join(', ') : (data.visual_features || ''),
    target_audience: data.target_audience || '',
    extreme_pain_point: data.extreme_pain_point || data.pain_point || '',
    core_solution: data.core_solution || '',
    visual_hook_suggestion: data.visual_hook_suggestion || '',
    key_differentiators: Array.isArray(data.key_differentiators) ? data.key_differentiators.join(', ') : (data.key_differentiators || ''),
    suggested_style: data.suggested_style || '简约',

    // 表单基础信息继承
    videoLanguage: formData.videoLanguage || 'Portuguese (Brazil)',
    videoDuration: formData.videoDuration || 30,
    numberOfVideos: formData.numberOfVideos || 1,
    customerEmail: formData.customerEmail || '',
    customerName: formData.customerName || '',
    customerId: formData.customerId || '',

    product_image_base64: productImageBase64,
    product_public_image_url: productPublicImageUrl || formData.product_public_image_url || ''
  }
}];

