  (() => {
    // 1. 提取表单数据与时长
    const formData = $('产品信息').first().json || {};
    const dur = parseInt(formData.videoDuration) || 20;

    // 2. 提取 Node D 的输出内容
    let nodeDContent = $('节点 D：最终格式组装 (The Synthesizer)').first().json.choices[0].message.content;
    let visualPrompt = '';
    let narration = '';

    try {
      const parsed = JSON.parse(nodeDContent.replace(/```json/gi, '').replace(/```/g, '').trim());
      visualPrompt = parsed.visual_prompt || parsed.full_prompt || parsed.prompt || nodeDContent;
      narration = parsed.narration || '';
    } catch(e) {
      visualPrompt = nodeDContent;
    }

    // 容错：如果 Node D 漏了台词，直接回溯从 Node C 抓取
    if (!narration) {
      try {
        const nodeCContent = $('节点 C：台词精修与字数绝对控制 (The Script Supervisor)').first().json.choices[0].message.content;
        const parsedC = JSON.parse(nodeCContent.replace(/```json/gi, '').replace(/```/g, '').trim());
        narration = parsedC.narration || '';
      } catch(e) {}
    }

    // 3. 强力拼接多语言控制指令（强制锁定巴西葡语原生发音）
    let finalPrompt = visualPrompt;
    if (narration) {
      finalPrompt += `\n\n【⚠️ AUDIO & LANGUAGE INSTRUCTION - STRICT ENFORCEMENT】\nThe character in the video MUST speak ONLY in fluent Brazilian Portuguese (pt-BR). Under NO circumstances should Chinese speech be generated. Native Brazilian Portuguese accent and natural lip-sync matching the script below are strictly required.\n\nFALA EM PORTUGUÊS DO BRASIL (台词内容，仅作为发音严禁在画面中显示字幕):\n"${narration}"`;
    }

    // 4. 提取产品图 URL
    const productImageUrl = $('📎 提取产品图URL').first().json.product_public_image_url || '';

    // 5. 构建多模态请求体
    const contentPayload = [
      { type: 'text', text: finalPrompt }
    ];

    if (productImageUrl) {
      contentPayload.push({
        type: 'image_url',
        image_url: { url: productImageUrl }
      });
    }

    const requestBody = {
      model: 'doubao-seedance-2-5-260628',
      content: contentPayload,
      generate_audio: true,
      resolution: '480p',
      duration: dur,
      watermark: false
    };

    if (!productImageUrl) {
      requestBody.ratio = '9:16';
    }

    return requestBody;
  })()
}}

