const seedanceResp = $input.item.json;
const taskId = seedanceResp.id || seedanceResp.task_id;

// 🌟 从当前循环迭代读取变体与客户元数据（防止 DeepSeek A→B→C→D 链式调用覆盖原始数据）
let ctx = {};
try {
  const ref = $('🔄 逐提示词').item;
  if (ref && ref.json) ctx = ref.json;
} catch (e) { ctx = {}; }
const form = $('产品信息').first().json;

if (!taskId) {
  throw new Error('Seedance did not return task_id. Response: ' + JSON.stringify(seedanceResp).substring(0, 200));
}

return {
  json: {
    task_id: taskId,
    attempt: 0,
    max_attempts: 60,
    variant_index: ctx.variant_index || 1,
    hook_angle: ctx.hook_angle || '',
    total_variants: ctx.total_variants || 1,
    customer_email: ctx.customerEmail || form.customerEmail || '',
    customer_name: ctx.customerName || form.customerName || '',
    customer_id: ctx.customerId || form.customerId || '',
    product_name: ctx.product_name || '',
    total_duration: parseInt(ctx.videoDuration) || parseInt(form.videoDuration) || 20
  }
};

const statusResp = $input.item.json;
const prevData = $('⏳ 等待轮询').item.json;

// 核心修改：去掉了最外层的 [ ]，直接返回 Object
return {
  json: {
    ...prevData,
    status: statusResp.status || statusResp.state,
    video_url: statusResp.output?.video_url || statusResp.result?.video_url || statusResp.video_url || null,
    audio_url: statusResp.output?.audio_url || statusResp.result?.audio_url || null,
    raw_response: statusResp
  }
};

const data = $input.item.json;
const attempt = (data.attempt || 0) + 1;

if (attempt > (data.max_attempts || 60)) {
  throw new Error('Seedance task ' + data.task_id + ' timed out after ' + attempt + ' attempts');
}

// 核心修改：去掉了最外层的 [ ]，直接返回 Object
return {
  json: {
    ...data,
    attempt: attempt
  }
};

const data = $input.item.json;

// 提取 Seedance 2.5 返回的原生视频 URL
const videoUrl = data.video_url || data.raw_response?.content?.video_url || data.raw_response?.output?.video_url || data.raw_response?.result?.video_url || '';

if (!videoUrl) {
  throw new Error('Seedance 任务已完成，但未找到视频 URL。Response: ' + JSON.stringify(data.raw_response || data).substring(0, 300));
}

return {
  json: {
    final_video_url: videoUrl,
    // R2 上传文件名时间戳（统一在此生成，避免下游节点 $now 漂移导致文件名不一致）
    video_ts: $now.toFormat('yyyyMMddHHmmss'),
    total_duration: data.total_duration || 20,
    variant_index: data.variant_index || 1,
    hook_angle: data.hook_angle || '',
    total_variants: data.total_variants || 1,
    customer_email: data.customer_email || '',
    customer_name: data.customer_name || '',
    customer_id: data.customer_id || '',
    product_name: data.product_name || '',
    task_id: data.task_id,
    status: 'complete'
  }
};

// 因为切换到了 All Items 模式，这里改回 .first()
const product = $input.first().json;
const videoLang = product.videoLanguage || 'Portuguese (Brazil)';
const isPortuguese = videoLang.includes('Portuguese');
const count = parseInt(product.numberOfVideos) || 3;

// 9 种爆款 hook 角度池
const anglePool = [
  { pt: '翻车现场', en: 'Epic Fail Moment', style: 'panic, authentic, relatable', emotion_pt: 'desespero e frustração', emotion_en: 'desperation and frustration' },
  { pt: '素人见证', en: 'Real Person Testimonial', style: 'testimonial, tearful, grateful', emotion_pt: 'alívio e gratidão', emotion_en: 'relief and gratitude' },
  { pt: '极限测评', en: 'Extreme Challenge Test', style: 'extreme test, scientific, shocking', emotion_pt: 'choque e surpresa', emotion_en: 'shock and surprise' },
  { pt: '反差对比', en: 'Before vs After Split', style: 'split screen, dramatic contrast', emotion_pt: 'incredulidade e desejo', emotion_en: 'disbelief and desire' },
  { pt: '明星体验', en: 'Luxury Experience', style: 'glamorous, aspirational, premium', emotion_pt: 'admiração e vontade', emotion_en: 'admiration and craving' },
  { pt: '专家解析', en: 'Expert Breakdown', style: 'educational, authoritative', emotion_pt: 'confiança e respeito', emotion_en: 'confidence and trust' },
  { pt: '情景喜剧', en: 'Relatable Skit', style: 'funny, everyday humor', emotion_pt: 'identificação e riso', emotion_en: 'relatability and laughter' },
  { pt: '悬念揭秘', en: 'Mystery Reveal', style: 'suspense, curiosity, reveal', emotion_pt: 'curiosidade intensa', emotion_en: 'intense curiosity' },
  { pt: '快节奏混剪', en: 'Fast Montage', style: 'high energy, rapid cuts, dynamic', emotion_pt: 'empolgação total', emotion_en: 'total excitement' }
];

const selected = [];
for (let i = 0; i < count; i++) {
  const angle = anglePool[i % anglePool.length];
  selected.push({
    ...product,
    variant_index: i + 1,
    hook_angle: isPortuguese ? angle.pt : angle.en,
    hook_style: angle.style,
    hook_emotion: isPortuguese ? angle.emotion_pt : angle.emotion_en,
    total_variants: count
  });
}

// 裂变输出：吐出包含 3 个变体的数组
return selected.map(item => ({ json: item }));

